  fiscalChanged(){const preview=document.getElementById('payslip-fiscal-preview');if(!preview)return;const rcId=document.getElementById('payslip-rc')?.value||'',fiscalSource=document.getElementById('payslip-fiscal-source')?.value||'auto';const register=this.registerFor({rcId,fiscalSource});const fiscal=window.SariCore.payroll.resolveFiscalIdentifiers(this.state.settings||{},register);preview.innerHTML=`${this.t('fiscalIdentifiers','Identifiants fiscaux')} : <b>NIF</b> ${SariUtils.escapeHtml(fiscal.nif||'—')} • <b>RC</b> ${SariUtils.escapeHtml(fiscal.rc||'—')} • <b>NAI</b> ${SariUtils.escapeHtml(fiscal.nai||'—')} • <b>NIS</b> ${SariUtils.escapeHtml(fiscal.nis||'—')}${fiscal.registerName?` <span class="text-sari-blue">(${SariUtils.escapeHtml(fiscal.registerName)})</span>`:''}`;},
