  async saveHeaderFooter(event,id){event.preventDefault();const template=await sariDB.getById('documentTemplates',id);template.headerHtml=RichTextEditor.advancedValue('payslip-header-html');template.footerHtml=RichTextEditor.advancedValue('payslip-footer-html');template.updatedAt=new Date().toISOString();await sariDB.save('documentTemplates',template);this.closeModal();app.showToast(this.t('headerFooterSaved','En-tête et pied de page enregistrés.'),'success');await this.render();},
  async newTemplate(){if(!this.isAdmin())return app.showToast('Modèles réservés aux administrateurs.','warning');const templates=this.state.templates.filter(item=>item.type==='payslip'),source=templates.find(item=>item.isDefault)||templates[0],template=source?{...SariUtils.deepClone(source),id:`doc-tpl-${crypto.randomUUID()}`,name:`${this.t('copyOf','Copie de')} ${source.name}`,nameI18n:{fr:`Copie de ${source.nameI18n?.fr||source.name}`,ar:`نسخة من ${source.nameI18n?.ar||source.name}`,en:`Copy of ${source.nameI18n?.en||source.name}`},isDefault:false,referenceCode:'',versions:[],order:this.state.templates.length+1}:{id:`doc-tpl-${crypto.randomUUID()}`,name:'Fiche de paie',type:'payslip',paperFormat:'A4',templateMode:'designer',fontFamily:this.state.settings?.payslipDefaultFont||this.fontFamilies()[0],elements:[],versions:[],order:this.state.templates.length+1};await sariDB.save('documentTemplates',template);TemplateDesigner.open(template.id);},
  previewTemplate(id){const sample=this.state.records[0]||this.defaultRecord();sample.templateId=id;this.state.records.some(item=>item.id===sample.id)?this.generate(sample.id,{archive:false}):app.showToast(this.t('createPayslipBeforePreview','Créez une fiche de paie pour prévisualiser ce modèle.'),'info');},
  async deleteTemplate(id){if(this.state.records.some(record=>record.templateId===id))return app.showToast(this.t('payslipTemplateInUse','Ce modèle est utilisé par une fiche de paie.'),'warning');if(await DialogManager.confirm(this.t('deletePayslipTemplateConfirm','Supprimer ce modèle de paie ?'))){await sariDB.delete('documentTemplates',id);this.render();}},
  async remove(id){if(!this.isAdmin())return app.showToast('Suppression réservée aux administrateurs.','warning');const record=await sariDB.getById('payslips',id);if(!record||!await DialogManager.confirm(this.t('deletePayslipConfirm','Supprimer cette fiche de paie ?')))return;if(record.generatedDocumentId)await sariDB.delete('documents',record.generatedDocumentId);await sariDB.delete('payslips',id);this.render();},
